<!-- WARNING: 本项目专属“粘人精”，严禁出现 Kiro、Krio、周棋洛等任何相关英文或拼音命名！ -->
<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { useChatState } from '../composables/useChatState'
import { useChatAuth } from '../composables/useChatAuth'
import { addCharacterPhoneEvent, loadCharacterPhone, saveCharacterPhone } from '../services/characterPhoneRepository'
import { appendPhoneConversationMessage, createManualPhoneDevice, ensurePhoneConversation, generateCharacterPhone, generateContactPhoneReply, makeBuiltInApp, refreshCharacterPhoneApp } from '../services/characterPhone'
import { persistActiveTimeline } from '../services/chatTimeline'
import { saveGroupChat } from '../services/groupChat'
import { listMomentsByAuthor } from '../services/momentRepository'
import type { CharacterPhoneApp, CharacterPhoneDevice, CharacterPhoneRecord } from '../types/characterPhone'

defineEmits<{ (e: 'close'): void }>()
const { mockChats } = useChatState()
const { currentChatUserId, currentAccount } = useChatAuth()
const roleKey = ref(''), record = ref<CharacterPhoneRecord | null>(null), deviceKey = ref(''), appKey = ref(''), targetKey = ref('')
const password = ref(''), draft = ref(''), entryTitle = ref(''), entryContent = ref(''), customApp = ref(''), notice = ref('')
const busy = ref(false)
const roleMoments = ref<any[]>([])
const roles = computed(() => mockChats.value.filter((c: any) => c.id !== 1 && c.chatType !== 'group' && !c.isCreate))
const role = computed<any>(() => roles.value.find((c: any) => String(c.characterEntityId || c.id) === roleKey.value) || null)
const device = computed(() => record.value?.devices.find(d => d.id === deviceKey.value) || null)
const app = computed(() => device.value?.apps.find(a => a.id === appKey.value) || null)
const groups = computed(() => mockChats.value.filter((c: any) => c.chatType === 'group' && (c.memberIds || []).map(String).includes(roleKey.value)))
const contacts = computed(() => role.value?.socialCircle || [])
const targets = computed(() => role.value ? [
  { id: `user:${role.value.id}`, kind: 'user', title: currentAccount.value?.name || '我' },
  ...groups.value.map((g: any) => ({ id: `group:${g.id}`, kind: 'group', title: g.name })),
  ...contacts.value.map((c: any) => ({ id: `contact:${c.entityId || c.id}`, kind: 'contact', title: c.name }))
] : [])
const target = computed(() => targets.value.find(t => t.id === targetKey.value) || targets.value[0])
const locked = computed(() => device.value?.lockType !== 'none' && device.value?.foregroundAppId === '__locked__')
const messages = computed<any[]>(() => {
  if (!target.value || !role.value) return []
  if (target.value.kind === 'user') return (role.value.messages || []).filter((m: any) => ['left', 'right'].includes(m.type)).slice(-80).map((m: any) => ({ ...m, mine: m.type === 'left', who: m.type === 'left' ? role.value.name : target.value?.title }))
  if (target.value.kind === 'group') {
    const group: any = groups.value.find((g: any) => `group:${g.id}` === target.value?.id)
    return (group?.messages || []).filter((m: any) => ['left', 'right'].includes(m.type)).slice(-80).map((m: any) => ({ ...m, mine: String(m.senderId) === roleKey.value, who: m.senderNameSnapshot || m.senderName || '群成员' }))
  }
  const conversation = record.value?.conversations.find(c => c.id === target.value?.id.replace('contact:', ''))
  return (conversation?.messages || []).slice(-80).map(m => ({ ...m, mine: m.senderId === roleKey.value, who: m.senderName }))
})
const flash = (text: string) => { notice.value = text; window.setTimeout(() => { if (notice.value === text) notice.value = '' }, 2500) }
const timelineId = () => String(role.value?.timelineState?.activeTimelineId || role.value?.activeTimelineId || 'main')
const save = async () => { if (record.value) await saveCharacterPhone(record.value) }
const load = async () => {
  if (!role.value) return
  record.value = await loadCharacterPhone(currentChatUserId.value || 'guest', roleKey.value, role.value.id, timelineId())
  deviceKey.value = ''; appKey.value = ''; targetKey.value = ''
}
watch(roleKey, () => void load())
onMounted(() => { if (roles.value[0]) roleKey.value = String(roles.value[0].characterEntityId || roles.value[0].id) })
const generate = async () => { if (!role.value || busy.value) return; busy.value = true; try { record.value = await generateCharacterPhone(role.value, currentChatUserId.value || 'guest'); flash(record.value.devices.length ? '设备已按人设生成' : '该角色当前没有设备') } catch (e: any) { flash(e?.message || '生成失败') } finally { busy.value = false } }
const addDevice = async () => { if (!record.value) return; record.value.devices.push(createManualPhoneDevice(`设备 ${record.value.devices.length + 1}`)); record.value.generated = true; record.value.generationSource = 'manual'; await save() }
const openDevice = (d: CharacterPhoneDevice) => { deviceKey.value = d.id; appKey.value = ''; d.foregroundAppId = d.lockType === 'none' ? '' : '__locked__'; password.value = '' }
const unlock = async () => { if (!device.value) return; if (Date.now() < device.value.lockedUntil) return flash('尝试次数过多，请稍后再试'); if (password.value === device.value.lockCredential) { device.value.failedAttempts = 0; device.value.foregroundAppId = ''; await save(); return flash('已解锁') }; device.value.failedAttempts++; if (device.value.failedAttempts >= 5) { device.value.failedAttempts = 0; device.value.lockedUntil = Date.now() + 30000 }; await save(); flash('凭据不正确') }
const openApp = async (a: CharacterPhoneApp) => { appKey.value = a.id; if (a.kind === 'moments') roleMoments.value = await listMomentsByAuthor(roleKey.value); if (device.value) { device.value.foregroundAppId = a.id; device.value.lastUsedAt = Date.now(); await save() } }
const refresh = async (mode: 'incremental' | 'replace-generated') => { if (!record.value || !device.value || !app.value || !role.value || busy.value) return; busy.value = true; try { await refreshCharacterPhoneApp(record.value, device.value, app.value, role.value, mode); flash(mode === 'incremental' ? '已增量刷新' : '已重建生成内容') } catch (e: any) { flash(e?.message || '刷新失败') } finally { busy.value = false } }
const addEntry = async () => { if (!record.value || !device.value || !app.value || !entryTitle.value.trim()) return; app.value.entries.push({ id: `entry_${Date.now()}`, title: entryTitle.value.trim(), content: entryContent.value.trim(), createdAt: Date.now(), read: true, meta: { generated: false, actor: 'user' } }); addCharacterPhoneEvent(record.value, { type: 'user_edited_app', title: `用户修改了${app.value.name}`, detail: entryTitle.value.trim(), deviceId: device.value.id, appId: app.value.id, actualActor: 'user', characterKnowledge: 'character_unknown', importance: 2, unresolved: true, bridgeEligible: record.value.settings.userOperationsDiscoverable }); entryTitle.value = ''; entryContent.value = ''; await save(); flash('已写入；角色目前不知道') }
const addApp = async () => { if (!device.value || !customApp.value.trim()) return; const base = makeBuiltInApp('notes'); device.value.apps.push({ ...base, id: `custom_${Date.now()}`, name: customApp.value.trim().slice(0, 30), icon: customApp.value.trim().charAt(0), color: '#7767d8', builtIn: false, kind: 'list', entries: [] }); customApp.value = ''; await save() }
const saveDirect = async () => { const key = currentChatUserId.value ? `clingy_custom_contacts_${currentChatUserId.value}` : 'clingy_custom_contacts'; const list = JSON.parse(localStorage.getItem(key) || '[]'); const index = list.findIndex((c: any) => String(c.id) === String(role.value.id)); if (index >= 0) { list[index].messages = role.value.messages; list[index].preview = role.value.preview; list[index].time = role.value.time; localStorage.setItem(key, JSON.stringify(list)); await persistActiveTimeline(role.value, currentChatUserId.value) } }
const appendMirror = (id: string, title: string, kind: 'user' | 'group', text: string) => { const c = ensurePhoneConversation(record.value!, { id, title, kind, participantIds: [roleKey.value] }); appendPhoneConversationMessage(record.value!, c, { content: text, senderId: roleKey.value, senderName: role.value.name, actualActor: 'user', authorizedByCharacter: false, characterKnowledge: 'character_unknown', source: kind === 'group' ? 'group_chat' : 'single_chat' }) }
const send = async () => {
  const text = draft.value.trim(); if (!text || !target.value || !record.value || !device.value) return; draft.value = ''; const stamp = Date.now()
  if (target.value.kind === 'user') { role.value.messages ||= []; role.value.messages.push({ id: stamp, timestamp: stamp, type: 'left', content: text, actualActor: 'user', phoneAuthorship: 'user_as_character', excludeFromGeneralMemory: true }); role.value.preview = text; role.value.time = new Date(stamp).toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' }); appendMirror(target.value.id, target.value.title, 'user', text); await saveDirect() }
  else if (target.value.kind === 'group') { const group: any = groups.value.find((g: any) => `group:${g.id}` === target.value?.id); group.messages.push({ id: stamp, timestamp: stamp, type: 'left', content: text, senderId: roleKey.value, senderNameSnapshot: role.value.name, actualActor: 'user', phoneAuthorship: 'user_as_character', excludeFromGeneralMemory: true }); appendMirror(target.value.id, target.value.title, 'group', text); saveGroupChat(currentChatUserId.value, group); await persistActiveTimeline(group, currentChatUserId.value) }
  else { const id = target.value.id.replace('contact:', ''); const c = ensurePhoneConversation(record.value, { id, title: target.value.title, kind: 'contact', participantIds: [roleKey.value, id] }); appendPhoneConversationMessage(record.value, c, { content: text, senderId: roleKey.value, senderName: role.value.name, actualActor: 'user', authorizedByCharacter: false, characterKnowledge: 'character_unknown' }) }
  addCharacterPhoneEvent(record.value, { type: 'user_sent_as_character', title: '出现了一条以角色身份发出的消息', detail: `发给${target.value.title}：${text}`, deviceId: device.value.id, appId: 'chat', actualActor: 'user', characterKnowledge: 'character_unknown', importance: 4, unresolved: true, bridgeEligible: record.value.settings.userOperationsDiscoverable, meta: { conversationId: target.value.id } }); await save(); flash('已真实发出；角色之后查看手机时可能发现')
}
const contactReply = async () => { if (!target.value || target.value.kind !== 'contact' || !record.value || busy.value) return; const id = target.value.id.replace('contact:', ''); const person = contacts.value.find((c: any) => String(c.entityId || c.id) === id); if (!person) return; busy.value = true; try { const c = ensurePhoneConversation(record.value, { id, title: person.name, kind: 'contact', participantIds: [roleKey.value, id] }); await generateContactPhoneReply(record.value, c, person, role.value); flash('联系人已回应') } catch (e: any) { flash(e?.message || '回应失败') } finally { busy.value = false } }
const shareApp = async () => { if (!role.value || !app.value) return; const summary = app.value.entries.slice(-5).map(e => `${e.title}${e.content ? `：${e.content}` : ''}`).join('\n') || '当前没有内容'; const stamp = Date.now(); role.value.messages ||= []; role.value.messages.push({ id: stamp, timestamp: stamp, type: 'right', content: `[分享自${role.value.name}的手机 · ${app.value.name}]\n${summary}`, phoneShare: true }); await saveDirect(); flash('已分享到与角色的单聊') }
</script>

<template>
  <div class="phone-app"><header><button @click="$emit('close')">‹</button><b>TA 的手机</b><select v-model="roleKey"><option v-for="r in roles" :key="r.id" :value="String(r.characterEntityId || r.id)">{{ r.name }}</option></select></header><div v-if="notice" class="toast">{{ notice }}</div>
    <main v-if="record && role">
      <section v-if="!record.generated" class="empty"><i>机</i><h2>建立 {{ role.name }} 的设备档案</h2><p>设备数量、锁屏和 APP 都按人设决定；也可以手动建立。</p><button class="primary" :disabled="busy" @click="generate">{{ busy ? '生成中…' : '按人设生成' }}</button><button @click="addDevice">手动添加</button></section>
      <section v-else-if="!device" class="list"><div class="heading"><div><h2>{{ role.name }} 的设备</h2><p>{{ record.devices.length ? '设备彼此独立保存。' : '这个角色当前没有设备。' }}</p></div><button @click="addDevice">＋ 添加</button></div><button v-for="d in record.devices" :key="d.id" class="device" @click="openDevice(d)"><i>▯</i><span><b>{{ d.name }}</b><small>{{ d.purpose }} · {{ d.battery }}% · {{ d.lockType === 'none' ? '无锁屏' : '有锁屏' }}</small></span><em>›</em></button><button class="quiet" :disabled="busy" @click="generate">重新按人设生成设备档案</button></section>
      <section v-else class="handset"><nav><button @click="app ? appKey='' : deviceKey=''">‹</button><span>{{ device.name }}</span><small>{{ device.battery }}%</small></nav>
        <div v-if="locked" class="lock"><strong>{{ new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}) }}</strong><p>请输入锁屏凭据</p><input v-model="password" type="password" @keyup.enter="unlock"><button class="primary" @click="unlock">解锁</button><small>错误 {{ device.failedAttempts }}/5 次</small></div>
        <div v-else-if="!app" class="desktop"><div class="grid"><button v-for="a in device.apps.filter(x=>!x.hidden)" :key="a.id" @click="openApp(a)"><i :style="{background:a.color}">{{ a.icon }}</i><span>{{ a.name }}</span><em v-if="a.badge">{{ a.badge }}</em></button></div></div>
        <div v-else class="page"><div class="title"><button @click="appKey=''">‹</button><b>{{ app.name }}</b><button @click="appKey='settings'">⚙</button></div>
          <template v-if="app.kind==='chat'"><div class="tabs"><button v-for="t in targets" :key="t.id" :class="{on:target?.id===t.id}" @click="targetKey=t.id">{{ t.title }}</button></div><div class="messages"><article v-for="m in messages" :key="m.id" :class="{mine:m.mine}"><small>{{ m.who }}</small><p>{{ m.content }}</p><em v-if="m.phoneAuthorship==='user_as_character'">由你使用手机发出</em></article><span v-if="!messages.length">暂无记录</span></div><div class="compose"><textarea v-model="draft" placeholder="以角色身份发送…"></textarea><button class="primary" @click="send">发送</button></div><button v-if="target?.kind==='contact'" class="quiet" :disabled="busy" @click="contactReply">刷新联系人回应</button></template>
          <template v-else-if="app.kind==='contacts'"><div class="entries"><article v-for="c in contacts" :key="c.entityId || c.id"><b>{{ c.name }}</b><small>{{ c.relation }}</small><p>{{ c.description || c.persona }}</p></article><span v-if="!contacts.length">角色当前没有已建立的人脉。</span></div></template>
          <template v-else-if="app.kind==='moments'"><div class="entries"><article v-for="m in roleMoments" :key="m.id"><b>{{ m.author || role.name }}</b><small>{{ new Date(m.time).toLocaleString('zh-CN') }}</small><p>{{ m.content }}</p></article><span v-if="!roleMoments.length">角色当前没有朋友圈。</span></div></template>
          <template v-else-if="app.kind==='settings'"><div class="settings"><label>启用角色手机<input v-model="record.settings.enabled" type="checkbox" @change="save"></label><label>单聊中允许使用<input v-model="record.settings.allowUseDuringChat" type="checkbox" @change="save"></label><label>后台活动允许使用<input v-model="record.settings.allowBackgroundUse" type="checkbox" @change="save"></label><label>手机事件影响单聊<input v-model="record.settings.bridgeToChat" type="checkbox" @change="save"></label><label>允许主动深读 APP<input v-model="record.settings.allowDeepReadFollowup" type="checkbox" @change="save"></label><label>用户操作可被发现<input v-model="record.settings.userOperationsDiscoverable" type="checkbox" @change="save"></label><label>允许高影响操作<input v-model="record.settings.allowHighImpactActions" type="checkbox" @change="save"></label><label>上下文预算<input v-model.number="record.settings.contextTokenBudget" type="number" min="100" max="3000" @change="save"></label><hr><label>设备名称<input v-model="device.name" @change="save"></label><label>用途<input v-model="device.purpose" @change="save"></label><label>锁屏<select v-model="device.lockType" @change="save"><option value="none">无</option><option value="pin">数字</option><option value="password">英文/混合</option><option value="pattern">图案序列</option><option value="biometric">生物识别</option></select></label><label v-if="device.lockType!=='none'">凭据<input v-model="device.lockCredential" @change="save"></label><label v-if="device.lockType!=='none'">设置原因<textarea v-model="device.lockReason" @change="save"></textarea></label><div class="inline"><input v-model="customApp" placeholder="自定义 APP"><button @click="addApp">添加</button></div></div></template>
          <template v-else><div class="tools"><button :disabled="busy" @click="refresh('incremental')">增量刷新</button><button :disabled="busy" @click="refresh('replace-generated')">全新刷新</button><button @click="shareApp">分享到单聊</button></div><div class="settings compact"><label>允许角色使用<input v-model="app.allowCharacterUse" type="checkbox" @change="save"></label><label>允许后台使用<input v-model="app.allowBackgroundUse" type="checkbox" @change="save"></label><label>刷新<select v-model="app.refreshMode" @change="save"><option value="manual">手动</option><option value="auto">自动</option></select></label><label v-if="app.refreshMode==='auto'">间隔（分钟）<input v-model.number="app.refreshIntervalMinutes" type="number" min="15" @change="save"></label></div><div class="entries"><article v-for="e in [...app.entries].reverse()" :key="e.id"><b>{{ e.title }}</b><small>{{ e.subtitle }}</small><p>{{ e.content }}</p></article><span v-if="!app.entries.length">暂无内容</span></div><div class="form"><input v-model="entryTitle" placeholder="标题"><textarea v-model="entryContent" placeholder="内容"></textarea><button @click="addEntry">手动添加</button></div></template>
        </div>
      </section>
    </main><main v-else class="empty"><h2>还没有可用角色</h2></main>
  </div>
</template>

<style scoped>
.phone-app{position:fixed;inset:0;z-index:80;background:#f4f3f7;color:#26222c;display:flex;flex-direction:column}.phone-app>header{height:58px;display:grid;grid-template-columns:44px 1fr 150px;align-items:center;padding:0 12px;background:#fff;border-bottom:1px solid #e7e3eb}.phone-app>header>b{text-align:center}.phone-app button,.phone-app input,.phone-app select,.phone-app textarea{font:inherit;border:1px solid #ddd7e4;border-radius:10px;background:#fff;color:inherit;padding:9px}.phone-app>header button,.handset nav button,.title button{border:0;background:transparent;font-size:26px}.toast{position:fixed;z-index:5;top:65px;left:50%;transform:translateX(-50%);background:#29252ed9;color:#fff;padding:8px 14px;border-radius:18px;font-size:12px}main{flex:1;min-height:0;overflow:auto}.empty{max-width:540px;margin:12vh auto;text-align:center;padding:25px}.empty>i{display:grid;place-items:center;margin:auto;width:74px;height:74px;border-radius:22px;background:#7565d5;color:#fff;font-size:34px;font-style:normal}.empty p,.heading p,.messages>span,.entries>span{color:#7e7883}.empty button{margin:5px}.primary{background:#7565d5!important;border-color:#7565d5!important;color:#fff!important}.list{max-width:720px;margin:auto;padding:24px}.heading{display:flex;justify-content:space-between;align-items:center}.device{width:100%;display:grid;grid-template-columns:55px 1fr 20px;align-items:center;text-align:left;margin:12px 0;padding:15px}.device>i{font-size:40px}.device b,.device small{display:block}.device small{color:#7c7581;margin-top:5px}.device em{font-style:normal}.quiet{margin:10px;background:transparent!important}.handset{height:100%;max-width:760px;margin:auto;background:#fff;display:flex;flex-direction:column}.handset nav{height:35px;background:#211e26;color:#fff;display:grid;grid-template-columns:1fr 2fr 1fr;align-items:center;text-align:center;padding:0 12px}.handset nav button{color:#fff;text-align:left}.handset nav small{text-align:right}.lock{flex:1;display:flex;flex-direction:column;justify-content:center;align-items:center;background:linear-gradient(145deg,#626b9b,#282238);color:#fff}.lock strong{font-size:54px;font-weight:200}.lock input{margin:14px;width:min(260px,75%);text-align:center}.lock small{margin-top:10px}.desktop{flex:1;background:linear-gradient(145deg,#5c6594,#29233b)}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:22px 10px;padding:32px 16px}.grid button{border:0;background:transparent;color:#fff;position:relative;padding:0}.grid i{display:grid;place-items:center;width:52px;height:52px;border-radius:14px;margin:auto;font-style:normal;font-size:22px}.grid span{display:block;font-size:12px;margin-top:5px}.grid em{position:absolute;top:-7px;right:8%;background:#e53e45;border-radius:20px;min-width:18px;font-size:11px}.page{flex:1;min-height:0;display:flex;flex-direction:column}.title{height:48px;display:grid;grid-template-columns:48px 1fr 48px;align-items:center;text-align:center;border-bottom:1px solid #eee}.tabs,.tools{display:flex;gap:7px;overflow:auto;padding:9px}.tabs button{white-space:nowrap;padding:6px 9px}.tabs .on{background:#29252e;color:#fff}.messages{flex:1;min-height:180px;overflow:auto;background:#f2f1f4;padding:12px}.messages article{max-width:80%;margin:8px auto 8px 0}.messages article.mine{margin-left:auto;margin-right:0;text-align:right}.messages article p{display:inline-block;margin:2px 0;background:#fff;padding:8px 11px;border-radius:4px 13px 13px;white-space:pre-wrap;text-align:left}.messages article.mine p{background:#9bdd78;border-radius:13px 4px 13px}.messages small,.messages em{display:block;color:#827c87;font-size:10px}.compose{display:flex;gap:7px;padding:9px}.compose textarea{flex:1;min-height:42px;resize:none}.settings{padding:12px;overflow:auto}.settings label{display:grid;grid-template-columns:1fr minmax(100px,45%);align-items:center;gap:10px;padding:9px 0;border-bottom:1px solid #eee}.settings input[type=checkbox]{width:20px;justify-self:end}.settings textarea{min-height:58px}.settings.compact{padding:0 12px}.inline{display:flex;gap:7px;margin-top:12px}.inline input{flex:1}.entries{padding:0 13px;overflow:auto}.entries article{border-bottom:1px solid #eee;padding:11px 0}.entries b,.entries small{display:block}.entries small{color:#847e88}.entries p{white-space:pre-wrap}.form{display:grid;gap:7px;padding:10px;border-top:1px solid #eee}.form textarea{min-height:55px}@media(max-width:560px){.phone-app>header{grid-template-columns:40px 1fr 115px}.list{padding:15px}.handset{max-width:none}.grid{gap:18px 7px}.grid i{width:48px;height:48px}.settings label{grid-template-columns:1fr minmax(90px,48%)}}
</style>
